statementStructureSchemaProposal.typescriptInterfaceDraft:
/** 意見書・決議（category==="意見書"|"決議"）向けの任意拡張フィールド案。既存のBillVoteItemを置き換えず、後方互換な任意プロパティとして追加する想定（実装はしない）。 */
interface StatementBillExtension {
  /** 提出者の表現。委員会（proposerType==="committee"）の場合は既存のproposer（例："議会運営委員会"）で対応可能。
   *  会派・複数議員による共同提出（proposerType==="member"）の場合に備え、複数名を配列で保持できるようにする案。
   *  一次資料（議案書・会議録）に明記されている場合のみ設定し、推測で埋めない。 */
  proposerMembers?: {
    /** 議員名（members.jsonのIDが判明していればmemberIdも設定する。不明な場合は氏名のみで"確認中"にはしない＝氏名自体は一次資料に明記されているのが通常のため）。 */
    memberId?: string;
    memberName: string;
    /** 会派名。一次資料に記載がある場合のみ。 */
    faction?: string;
  }[];
  /** 意見書の提出先（宛先）。内閣総理大臣・関係大臣・衆参両院議長等、公式資料（意見書本文）に明記されている場合のみ設定する。
   *  一次資料に記載が無い、または未確認の場合は配列を設定せず、UI側は"確認中"等の表示に倒す。 */
  submissionTargets?: string[];
  /** 意見書のように外部機関へ提出する性質か（true）、決議のように対内的議決で完結するか（false）。
   *  category（意見書/決議）から機械的に導出できるため、このフィールド自体は必須ではなく、UI側の分岐に
   *  categoryを直接使う設計でも良い（重複管理を避けるため、実装時はcategory由来の判定を優先する）。 */
  isExternalSubmission?: boolean;
  /** 内容の要旨。一次資料（意見書・決議の本文、会議録の提案理由説明）から確認できた場合のみ設定する。
   *  特定の政治的立場を支持・批判しない中立的な要約に限る（riskRules.statementStructure参照）。
   *  一次資料はあるが中立的要約が困難と判断した場合は、このフィールドを設定せず、summary（既存の定型文）と
   *  出典PDFへの案内のみで運用する（無理に要約を作らない）。未確認の場合は"確認中"は使わず、単にフィールドを省略する
   *  （このフィールド自体が「確認できた場合のみ設定する」性質のため、値の有無で状態を表現できる）。 */
  contentSummary?: string;
}

petitionStructureSchemaProposal.typescriptInterfaceDraft:
/** 請願・陳情（category==="請願"|"陳情"）向けの任意拡張フィールド案。既存のBillVoteItemを置き換えず、後方互換な任意プロパティとして追加する想定（実装はしない）。 */
interface PetitionBillExtension {
  /** 紹介議員（請願の場合、地方自治法上、紹介議員が必要）。陳情には通常紹介議員は不要なため、
   *  category==="請願"のときのみ意味を持つ想定。一次資料（請願書・議案書・会議録）に紹介議員名の記載が
   *  ある場合のみ設定する。氏名は議会が公式に公表する情報であり、members.jsonのIDに解決できる場合は
   *  memberIdも併記する。 */
  introducingMembers?: {
    memberId?: string;
    memberName: string;
  }[];
  /** 請願者・陳情者（団体名等）。個人名を含む場合、公式資料（採択結果一覧・議案書）に既に公開されている
   *  範囲（団体の代表者名等）に限る。住所・連絡先等、公式資料が公開していない付随情報は一切追加しない。 */
  petitionerName?: string;
  /** 付託委員会。既存のcommitteeフィールドで対応可能なため、このプロパティは新設不要
   *  （petitionFieldCoverageで29/30と既に高い充足率のため、既存committeeフィールドの継続利用を提案）。 */
}
